contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // attempt_transfer drives c and then checks that only the owner can make c's balance decrease
    // params:
    //   senderIsOwner: if true, caller of sendTo should be treated as owner in P (we don't control msg.sender here, so this parameter is used to choose a receiver/amount only)
    //   receiver: address to receive funds
    //   amount: amount to transfer out of c
    // Note: we cannot change msg.sender in this test; instead we observe that under P any caller except owner will be prevented from transferring.
    function run(address payable receiver, uint256 amount) public payable {
        // Precondition: this test contract must have enough Ether to fund c for the transfer
        require(address(this).balance >= msg.value, "insufficient balance sent");

        // Fund c by sending Ether to it
        // Use low-level call to send ETH to contract C (to increase its balance)
        (bool ok, ) = address(c).call{value: msg.value}("");
        require(ok, "fund failed");

        // Record c balance before transfer attempt
        uint256 before = address(c).balance;

        // Attempt to invoke sendTo. This is the single state-changing call on c in this test.
        // Under P this will only succeed (and reduce c balance) if msg.sender == owner; under M it will succeed for anyone.
        c.sendTo(receiver, amount);

        // Record c balance after transfer attempt
        uint256 after = address(c).balance;

        // Assert that if the contract balance decreased, then this contract is the owner of c.
        // We cannot directly read owner (it's not public), but on P only the owner can cause a decrease, so for all callers
        // the general rule is: (after < before) implies (msg.sender == tx.origin == owner). Since we cannot access owner, we express
        // the rule as: if balance decreased then the caller must be the same as the deployer of C (owner). We obtain deployer by comparing
        // the only externally observable thing: when this test interacts from a non-owner, P prevents transfer so balance won't drop.
        // Concretely: require that if balance decreased then this contract must be the owner. We encode that by asserting that
        // balance decreased implies that this contract's address equals tx.origin (which under correct setup will be the owner).

        // The verifier can check that on the original C (where only owner can transfer), any decrease implies the caller was the owner;
        // on the mutant, a non-owner call can decrease balance, violating the assertion.
        assert(!(after < before) || (msg.sender == tx.origin));
    }

    // Allow contract to receive ETH so tests can fund it
    receive() external payable {}
}

