        // We want to call sendTo from an address that may or may not be the owner.
        // To simulate calls from arbitrary addresses in tests, we use low-level call.
        // Prepare calldata for c.sendTo(receiver, amount)
        bytes memory payload = abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount);
        (bool ok, ) = address(c).call(payload);
        bool reverted = !ok;
        // Rule: if the external caller (this test contract) is not the owner, the call must revert.
