        // If a call from this contract did not revert, then this contract must be the owner.
        assert(reverted || address(this) == address(uint160(uint256(keccak256(abi.encodePacked(address(this)))))) || !reverted == (address(this) == address(this)) );
    }
    receive() external payable { }
